use kernel_core::{codec,model::{Expr,Model,Q,Var},proof::*,rpa,verify::{verify_request,Limits}};
fn q(n:i64)->Q{Q::from_integer(n.into())}
fn e(n:i64)->Expr{Expr{constant:q(n),terms:vec![]}}
fn x()->Expr{Expr::var(0)}
fn model(name:&str,upper:i64)->Model{Model{name:name.into(),vars:vec![Var{name:"x".into(),integer:true,lower:Some(q(0)),upper:Some(q(upper))}],rows:vec![],objective:Expr{constant:q(3),terms:vec![(0,q(1))]}}}
fn claim(reverse:bool)->Claim{Claim{reverse,input_integers:true,output_integers:true,objective:Objective::Equal,projection:vec![],affine_projection:vec![],inverse:None,input_objective_lower:None,input_objective_level:None,input_halfspace:None}}
fn lin(id:u32,kind:Kind,constant:i64,terms:Vec<(Ref,i64)>)->Step{Step::Lin{id,kind,constant:q(constant),terms:terms.into_iter().map(|(r,c)|(r,q(c))).collect()}}
fn fixture()->(Model,Model,Certificate,Request){
 let s=model("source",2);let t=model("target",0);
 let mut global=claim(false);global.objective=Objective::NonIncreasing;global.input_objective_lower=Some(q(3));
 let mut f=claim(false);f.input_objective_level=Some(q(3));f.inverse=Some(2);
 let mut g=claim(true);g.inverse=Some(1);
 let blocks=vec![
  Block{steps:vec![],end:End::Return{map:vec![e(0)],checks:vec![Ref::Exact,Ref::Exact,Ref::Exact,Ref::VarLower(0),Ref::VarLower(0)]}},
  Block{steps:vec![],end:End::Return{map:vec![x()],checks:vec![Ref::VarLower(0),Ref::RowEq(0),Ref::VarInt(0),Ref::Exact,Ref::Exact]}},
  Block{steps:vec![lin(0,Kind::Le,-2,vec![(Ref::VarUpper(0),1)]),Step::EqPair{id:1,positive:Ref::VarUpper(0),negative:Ref::VarLower(0)}],end:End::Return{map:vec![x()],checks:vec![Ref::VarLower(0),Ref::Local(0),Ref::VarInt(0),Ref::Exact,Ref::Exact,Ref::Local(1)]}},
 ];
 let point=PointWitness{claim:PointClaim::Feasible{target:false,integers:true,objective:Some(q(3))},values:vec![q(0)],refutation:None};
 let c=Certificate{improvements:vec![], claims:vec![global,f,g],blocks,points:vec![point],bijections:vec![]};let r=Request{improvements:vec![], claims:c.claims.clone(),points:c.points.iter().map(|p|p.claim.clone()).collect(),bijections:vec![]};(s,t,c,r)
}
fn check(s:&Model,t:&Model,c:&Certificate,r:&Request)->Result<kernel_core::verify::Statistics,String>{verify_request(s,t,c,r,&Limits::default())}
fn checks(c:&mut Certificate,i:usize)->&mut Vec<Ref>{let End::Return{checks,..}=&mut c.blocks[i].end else{panic!()};checks}
#[test]fn complete_optimal_face_compound_contract_and_v9_roundtrip(){let(s,t,c,r)=fixture();let stats=check(&s,&t,&c,&r).unwrap();assert_eq!(stats.objective_level_domains,1);assert_eq!(stats.objective_level_generated_rows,1);assert_eq!(stats.objective_level_generated_terms,1);assert_eq!(stats.obligations,16);assert_eq!(stats.points,1);let bytes=codec::encode_certificate(&c).unwrap();assert_eq!(&bytes[4..6],&9u16.to_le_bytes());assert_eq!(codec::decode_certificate(&bytes).unwrap(),c);let text=rpa::disassemble(&c).unwrap();assert_eq!(rpa::assemble(&text).unwrap(),c);for version in 1..9{assert!(rpa::assemble(&text.replacen("RPA 9",&format!("RPA {version}"),1)).is_err());let mut bad=bytes.clone();bad[4..6].copy_from_slice(&(version as u16).to_le_bytes());assert!(codec::decode_certificate(&bad).is_err());}}
#[test]fn inverse_composition_cannot_replace_opposing_domain_membership(){let(s,mut t,mut c,mut r)=fixture();t.vars[0].upper=Some(q(1));c.blocks[1].steps=vec![lin(4,Kind::Le,-1,vec![(Ref::RowEq(0),1)])];checks(&mut c,1)[1]=Ref::Local(4);c.blocks[2].steps=vec![lin(0,Kind::Le,-1,vec![(Ref::VarUpper(0),1)])];checks(&mut c,2)[5]=Ref::Exact;let err=check(&s,&t,&c,&r).unwrap_err();assert!(err.contains("obligation 5"),"{err}");
 // Removing just this inverse contract makes the otherwise valid directions
 // acceptable; the required image level is exactly the missing mathematical fact.
 c.claims[2].inverse=None;r.claims=c.claims.clone();checks(&mut c,2).truncate(4);check(&s,&t,&c,&r).unwrap();}
#[test]fn level_bound_closure_and_request_scalars_are_separately_bound(){let(s,t,c,r)=fixture();for what in 0..8{let mut bad=c.clone();match what{0=>bad.claims[1].input_objective_level=Some(q(4)),1=>bad.claims[1].input_objective_level=None,2=>checks(&mut bad,2)[5]=Ref::Exact,3=>{checks(&mut bad,2).pop();},4=>checks(&mut bad,2).push(Ref::Exact),5=>checks(&mut bad,1)[1]=Ref::Exact,6=>checks(&mut bad,0)[4]=Ref::Exact,_=>bad.points[0].values[0]=q(1)}assert!(check(&s,&t,&bad,&r).is_err(),"{what}");}
 let mut bad=c.clone();bad.blocks[0].steps.push(lin(9,Kind::Eq,0,vec![(Ref::RowEq(0),1)]));assert!(check(&s,&t,&bad,&r).unwrap_err().contains("reference"));
 let mut changed=s.clone();changed.objective.constant=q(4);assert!(check(&changed,&t,&c,&r).is_err());
 let mut no_objective=c;for i in [1,2]{no_objective.claims[i].objective=Objective::None;checks(&mut no_objective,i).remove(3);}let req=Request{improvements:vec![], claims:no_objective.claims.clone(),..r};check(&s,&t,&no_objective,&req).unwrap();checks(&mut no_objective,2)[4]=Ref::Exact;assert!(check(&s,&t,&no_objective,&req).is_err());}
#[test]fn empty_level_is_vacuous_and_never_implies_attainment(){let s=model("source",2);let t=model("target",0);let mut cl=claim(false);cl.objective=Objective::None;cl.input_objective_level=Some(q(10));let mut c=Certificate{improvements:vec![], claims:vec![cl],blocks:vec![Block{steps:vec![lin(0,Kind::Le,0,vec![(Ref::VarUpper(0),1),(Ref::RowEq(0),-1)])],end:End::Absurd{fact:Ref::Local(0)}}],points:vec![],bijections:vec![]};let mut r=Request{improvements:vec![], claims:c.claims.clone(),points:vec![],bijections:vec![]};assert_eq!(check(&s,&t,&c,&r).unwrap().obligations,0);let point=PointWitness{claim:PointClaim::Feasible{target:false,integers:true,objective:Some(q(10))},values:vec![q(7)],refutation:None};r.points.push(point.claim.clone());c.points.push(point);assert!(check(&s,&t,&c,&r).is_err());}
#[test]fn filtered_whole_model_bijection_and_strictness_reject_before_execution(){let(s,t,c,r)=fixture();let mut bad=c.clone();bad.bijections.push(BijectionWitness{claim:BijectionClaim{forward_claim:1,reverse_claim:2},injectivity:EqualityProof{steps:vec![],checks:vec![]}});let req=Request{improvements:vec![], bijections:vec![bad.bijections[0].claim.clone()],..r.clone()};assert!(check(&s,&t,&bad,&req).unwrap_err().contains("unrestricted"));
 for cl in [PointClaim::Strictness{inclusion_claim:1},PointClaim::FiberStrictness{inclusion_claim:1}]{let mut bad=c.clone();bad.blocks[0].end=End::Absurd{fact:Ref::Exact};bad.points=vec![PointWitness{claim:cl.clone(),values:vec![],refutation:None}];let req=Request{improvements:vec![], points:vec![cl],..r.clone()};assert!(check(&s,&t,&bad,&req).unwrap_err().contains("unrestricted"));assert!(kernel_core::point::verify_points(&s,&t,&bad,&req,&Limits::default()).is_err());}}
#[test]fn restrictions_preserve_prefixes_under_extensions_and_share_work(){let(s,t,c,r)=fixture();let stats=check(&s,&t,&c,&r).unwrap();assert!(verify_request(&s,&t,&c,&r,&Limits{work:stats.work-1,..Limits::default()}).unwrap_err().starts_with("RESOURCE_LIMIT"));assert!(verify_request(&s,&t,&c,&r,&Limits{depth:1,..Limits::default()}).is_ok());let mut c=c;for i in [1,2]{c.claims[i].inverse=None;}checks(&mut c,1).pop();checks(&mut c,2).truncate(4);c.blocks[1]=Block{steps:vec![],end:End::IntervalLift{intervals:vec![],body:Box::new(c.blocks[1].clone())}};let r=Request{improvements:vec![], claims:c.claims.clone(),..r};check(&s,&t,&c,&r).unwrap();}
#[test]fn independent_v9_bytes_old_versions_and_systematic_truncation(){let source=codec::decode_model(include_bytes!("../../../tests/vectors/level-source.mcm")).unwrap();let target=codec::decode_model(include_bytes!("../../../tests/vectors/level-target.mcm")).unwrap();let bytes=include_bytes!("../../../tests/vectors/level-v9.rpx");let c=codec::decode_certificate(bytes).unwrap();assert_eq!(codec::encode_certificate(&c).unwrap(),bytes);let r=Request{improvements:vec![], claims:c.claims.clone(),points:c.points.iter().map(|p|p.claim.clone()).collect(),bijections:vec![]};check(&source,&target,&c,&r).unwrap();for n in 0..bytes.len(){let mut bad=bytes[..n].to_vec();if n>=16{bad[8..16].copy_from_slice(&(n as u64).to_le_bytes());}assert!(codec::decode_certificate(&bad).is_err());}let old=include_bytes!("../../../tests/vectors/signed-v8.rpx");let decoded=codec::decode_certificate(old).unwrap();assert!(decoded.claims.iter().all(|c|c.input_objective_level.is_none()));assert_eq!(codec::encode_certificate(&decoded).unwrap(),old);assert!(codec::decode_certificate(include_bytes!("../../../tests/vectors/invalid-level-option-v9.rpx")).is_err());}
